or -->\\r\\n      <div class=\\\"country-selector\\\" @click=\\\"toggleCountryDropdown\\\">\\r\\n        <span class=\\\"country-flag\\\">{{ selectedCountry.flag }}</span>\\r\\n        <span class=\\\"country-code\\\">+{{ selectedCountry.dialCode }}</span>\\r\\n        <i class=\\\"fas fa-chevron-down dropdown-icon\\\"></i>\\r\\n      </div>\\r\\n      \\r\\n      <!-- Phone Number Input -->\\r\\n      <input\\r\\n        v-model=\\\"phoneNumber\\\"\\r\\n        type=\\\"tel\\\"\\r\\n        class=\\\"phone-input\\\"\\r\\n        :class=\\\"{ 'is-invalid': hasError }\\\"\\r\\n        :placeholder=\\\"placeholder || $t('enter_phone_number')\\\"\\r\\n        @input=\\\"onInput\\\"\\r\\n        @blur=\\\"validatePhone\\\"\\r\\n        @focus=\\\"onFocus\\\"\\r\\n      />\\r\\n      \\r\\n      <!-- Country Dropdown -->\\r\\n      <div v-if=\\\"showCountryDropdown\\\" class=\\\"country-dropdown\\\" @click.stop>\\r\\n        <div class=\\\"country-search\\\">\\r\\n          <input\\r\\n            v-model=\\\"countrySearch\\\"\\r\\n            type=\\\"text\\\"\\r\\n            class=\\\"form-control\\\"\\r\\n            :placeholder=\\\"$t('search_country')\\\"\\r\\n            @input=\\\"filterCountries\\\"\\r\\n          />\\r\\n        </div>\\r\\n        <div class=\\\"country-list\\\">\\r\\n          <div\\r\\n            v-for=\\\"country in filteredCountries\\\"\\r\\n            :key=\\\"country.code\\\"\\r\\n            class=\\\"country-item\\\"\\r\\n            :class=\\\"{ active: selectedCountry.code === country.code }\\\"\\r\\n            @click=\\\"selectCountry(country)\\\"\\r\\n          >\\r\\n            <span class=\\\"country-flag\\\">{{ country.flag }}</span>\\r\\n            <span class=\\\"country-name\\\">{{ country.name }}</span>\\r\\n            <span class=\\\"country-dial-code\\\">+{{ country.dialCode }}</span>\\r\\n          </div>\\r\\n        </div>\\r\\n      </div>\\r\\n    </div>\\r\\n    \\r\\n    <!-- Error Message -->\\r\\n    <div v